def open_kitchens(hhmm: int) -> list[str]:
    """Branch names (sorted) whose kitchens take orders at hhmm."""
    open_branches = []
    for branch in KITCHEN_HOURS:
        start, end = KITCHEN_HOURS[branch]
        if start <= hhmm < end:
            open_branches.append(branch)
    return sorted(open_branches)
